/**
 * @param {number[]} nums
 * @param {number} x
 * @return {number}
 */
var minOperations = function(nums, x) {
    const n = nums.length;

    let total = 0;
    for (const num of nums) {
        total += num;
    }

    const target = total - x;
    let left = 0;
    let sum = 0;
    let res = -1;

    for (let right = 0; right < n; right++) {
        sum += nums[right];

        while (sum > target) {
            sum -= nums[left];
            left++;
        }

        if (sum === target) {
            res = Math.max(res, right - left + 1);
        }
    }

    return res === -1 ? -1 : n - res;
};
